package pe.edu.lab16.inscripciones;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import java.util.List;
@RestController @RequestMapping("/inscripciones") public class InscripcionController{private final InscripcionService s;public InscripcionController(InscripcionService s){this.s=s;}@GetMapping public List<Inscripcion> listar(){return s.listar();}@GetMapping("/{id}") public Inscripcion obtener(@PathVariable Long id){return s.obtener(id);}@PostMapping public ResponseEntity<Inscripcion> crear(@Valid @RequestBody InscripcionRequest r){return ResponseEntity.status(201).body(s.crear(r));}@PutMapping("/{id}") public Inscripcion actualizar(@PathVariable Long id,@Valid @RequestBody InscripcionRequest r){return s.actualizar(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){s.eliminar(id);return ResponseEntity.noContent().build();}}
